    "titleAr": "أكبر مساحة لمستطيل محيطه ثابت رقم 8",
    "difficulty": "medium",
    "questionEn": "What is the maximum area of a rectangle whose perimeter is fixed at $P = 44\\text{ cm}$?",
    "questionAr": "ما هي أكبر مساحة ممكنة لمستطيل محيطه ثابت ويساوي $P = 44\\text{ سم}$؟",
    "optionsEn": [
      "$121\\text{ cm}^2$ (Square of side $11\\text{ cm}$)",
      "$117\\text{ cm}^2$",
      "$125\\text{ cm}^2$",
      "$242\\text{ cm}^2$"
    ],
    "optionsAr": [
      "$121\\text{ سم}^2$ (مربع طول ضلعه $11\\text{ سم}$)",
      "$117\\text{ سم}^2$",
      "$125\\text{ سم}^2$",
      "$242\\text{ سم}^2$"
    ],
    "correctAnswer": "$121\\text{ cm}^2$ (Square of side $11\\text{ cm}$)",
    "correctIndex": 0,
    "hintEn": "Area A(x) = x(2S - x). Maximize by differentiating or completing the square.",
    "hintAr": "دالة المساحة $A(x) = x(2S - x)$. وتصل لأقصى قيمة عندما يتحول المستطيل لمربع.",
    "stepByStepSolutionEn": [
      "1. Perimeter: $2(x + y) = 44 \\implies x + y = 22 \\implies y = 22 - x$.",
      "2. Area: $A(x) = x(22 - x) = 22x - x^2$.",
      "3. $A'(x) = 22 - 2x = 0 \\implies x = 11$.",
      "4. Maximum area is $A(11) = 11 \\times 11 = 121\\text{ cm}^2$."
    ],
    "stepByStepSolutionAr": [
      "١. المحيط: $2(x + y) = 44 \\implies x + y = 22 \\implies y = 22 - x$.",
      "٢. المساحة: $A(x) = 22x - x^2$.",
      "٣. المشتقة: $A'(x) = 22 - 2x = 0 \\implies x = 11$.",
      "٤. أكبر مساحة هي $A = 11^2 = 121\\text{ سم}^2$ (عندما يكون مربعاً)."
    ],
    "teacherTipEn": "Among all rectangles of a given perimeter, the square encloses the greatest area.",
    "teacherTipAr": "من بين جميع المستطيلات ذات المحيط الثابت، المربع هو الذي يعطي أكبر مساحة."
