      "٣. دالة المساحة: $A(x) = 2x(3 - x^2) = 6x - 2x^3$.",
      "٤. المشتقة: $A'(x) = 6 - 6x^2 = 0 \\implies x^2 = 1 \\implies x = 1$.",
      "٥. أكبر مساحة هي $A(1) = 2(1)(2) = 4$ وحدة مربعة."
