    "hintAr": "لأي أسطوانة مغلقة ذات أقل مساحة سطحية، يجب أن يتساوى الارتفاع مع القطر بالكامل: $h = 2r$.",
    "stepByStepSolutionEn": [
      "1. Volume: $\\pi r^2 h = 128\\pi \\implies h = \\frac{128}{r^2}$.",
      "2. Total surface area: $S(r) = 2\\pi r^2 + 2\\pi r \\left(\\frac{128}{r^2}\\right) = 2\\pi r^2 + \\frac{256\\pi}{r}$.",
      "3. $S'(r) = 4\\pi r - \\frac{256\\pi}{r^2} = 0 \\implies 4r^3 = 256 = 256 \\implies r = 4\\text{ cm}$.",
      "4. Height: $h = \\frac{128}{16} = 8\\text{ cm}$. Total area is $6\\pi (4)^2 = 96\\pi\\text{ cm}^2$."
    ],
