    "titleAr": "عدد الجذور الحقيقية من إشارات القيم القصوى رقم 5",
    "difficulty": "hots",
    "questionEn": "For the cubic polynomial $f(x) = 2x^3 - 15x^2 + 1$, given that its local maximum value is positive and its local minimum value is negative ($f(x_{max}) \\cdot f(x_{min}) < 0$), how many distinct real roots does the equation $f(x) = 0$ possess?",
    "questionAr": "لكثيرة الحدود التكعيبية $f(x) = 2x^3 - 15x^2 + 1$، إذا كانت القيمة العظمى المحلية موجبة والقيمة الصغرى المحلية سالبة ($f(x_{max}) \\cdot f(x_{min}) < 0$)، فكم جذراً حقيقياً مختلفاً للمعادلة $f(x) = 0$؟",
    "optionsEn": [
      "Exactly 3 distinct real roots",
      "Exactly 1 real root",
      "Exactly 2 real roots",
      "No real roots"
    ],
    "optionsAr": [
      "٣ جذور حقيقية مختلفة بالضبط",
      "جذر حقيقي واحد فقط",
      "جذران حقيقيان مختلفان",
      "لا توجد جذور حقيقية"
    ],
    "correctAnswer": "Exactly 3 distinct real roots",
    "correctIndex": 0,
    "hintEn": "By the Intermediate Value Theorem, the graph must cross the x-axis 3 times if the local extrema lie on opposite sides of the x-axis.",
    "hintAr": "بنظرية القيمة المتوسطة، يجب أن يقطع المنحنى محور السينات ٣ مرات إذا كانت النهايتان المحليتان على جانبي المحور.",
    "stepByStepSolutionEn": [
      "1. The function is continuous with $\\lim_{x \\to -\\infty} f(x) = -\\infty$ and $\\lim_{x \\to \\infty} f(x) = +\\infty$.",
      "2. It increases to a positive local maximum $f(x_{max}) > 0$, crossing the x-axis once on $(-\\infty, x_{max})$.",
      "3. It decreases from the positive maximum to a negative local minimum $f(x_{min}) < 0$, crossing the x-axis a second time on $(x_{max}, x_{min})$.",
      "4. It increases from the negative minimum to $+\\infty$, crossing the x-axis a third time on $(x_{min}, \\infty)$.",
      "5. Therefore, there are exactly 3 distinct real roots."
    ],
    "stepByStepSolutionAr": [
      "١. الدالة متصلة ونهايتها عند $-\\infty$ سالبة وعند $+\\infty$ موجبة.",
      "٢. تتزايد الدالة لتبلغ نهاية عظمى موجبة، فتقطع محور السينات مرة أولى.",
      "٣. تتناقص من القيمة العظمى الموجبة إلى القيمة الصغرى السالبة، فتقطع محور السينات مرة ثانية.",
      "٤. تتزايد من القيمة الصغرى السالبة إلى $+\\infty$، فتقطع محور السينات مرة ثالثة.",
      "٥. إذن توجد ٣ جذور حقيقية مختلفة بالضبط."
    ],
    "teacherTipEn": "If f(x_max) * f(x_min) < 0 for a cubic, it ALWAYS has 3 distinct real roots.",
    "teacherTipAr": "إذا اختلف إشارتا العظمى والصغرى المحليتين في الدالة التكعيبية، فإن للمعادلة دائماً ٣ جذور حقيقية مختلفة."
